def sort_array_brute(nums):
    n = len(nums)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):                    # scan for the minimum, every position
            if nums[j] < nums[min_idx]:
                min_idx = j
        nums[i], nums[min_idx] = nums[min_idx], nums[i]
    return nums

