def sort_array(nums):
    def merge_sort(l, r):
        if l >= r:
            return
        mid = (l + r) // 2
        merge_sort(l, mid)                      # sort left half
        merge_sort(mid + 1, r)                   # sort right half
        merged = []
        i, j = l, mid + 1
        while i <= mid and j <= r:               # two-pointer merge
            if nums[i] <= nums[j]:
                merged.append(nums[i]); i += 1
            else:
                merged.append(nums[j]); j += 1
        while i <= mid:
            merged.append(nums[i]); i += 1
        while j <= r:
            merged.append(nums[j]); j += 1
        for k in range(l, r + 1):
            nums[k] = merged[k - l]

    merge_sort(0, len(nums) - 1)
    return nums

