#include <bits/stdc++.h>
using namespace std;

void mergeSort(vector<int>& nums, int l, int r) {
    if (l >= r) return;
    int mid = (l + r) / 2;
    mergeSort(nums, l, mid);                        // sort left half
    mergeSort(nums, mid + 1, r);                       // sort right half
    vector<int> merged;
    int i = l, j = mid + 1;
    while (i <= mid && j <= r) {                        // two-pointer merge
        if (nums[i] <= nums[j]) merged.push_back(nums[i++]);
        else merged.push_back(nums[j++]);
    }
    while (i <= mid) merged.push_back(nums[i++]);
    while (j <= r) merged.push_back(nums[j++]);
    for (int k = l; k <= r; k++) nums[k] = merged[k - l];
}

vector<int> sortArray(vector<int>& nums) {
    mergeSort(nums, 0, (int)nums.size() - 1);
    return nums;
}
